const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let sign = 1;
        if (buffer[offset] === 45) { // '-'
            sign = -1;
            offset++;
        }
        let res = 0;
        while (offset < buffer.length && buffer[offset] >= 48 && buffer[offset] <= 57) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res * sign;
    }

    const n = readInt();
    if (n === null) return;

    const a = new Int32Array(n);
    for (let i = 0; i < n; i++) {
        a[i] = readInt();
    }

    const INF = 2000000000;
    const L = new Int32Array(n);

    let cur = INF;
    for (let i = 0; i < n; i++) {
        if (cur !== INF) cur++;
        if (a[i] !== -1) {
            cur = Math.min(cur, a[i]);
        }
        L[i] = cur;
    }

    const ans = new Int32Array(n);
    cur = INF;
    for (let i = n - 1; i >= 0; i--) {
        if (cur !== INF) cur++;
        if (a[i] !== -1) {
            cur = Math.min(cur, a[i]);
        }
        ans[i] = Math.min(L[i], cur);
    }

    console.log(ans.join(' '));
}

solve();
